  @override
  Future<List<GeoPointMessage>> build(String objectId) async {
    final repository = await ref.watch(metroRepositoryProvider.future);

    return repository.getMetroLineInfo(objectId);
  }

  Future<void> showMetro() async {
    if (state.hasValue == false || state.valueOrNull == null || state.valueOrNull?.isEmpty == true) {
      return;
    }
    final metroRoute = state.value!;
    final mapOptions = MapObjectManagerSettings.selectedMarker();
    final mapManager = ref.read(mapObjectManagerProvider(
      named: mapOptions.name,
      layerId: mapOptions.layerId,
    ).notifier);

    await mapManager.removeAllPolyLines();

    await mapManager.addPolyLines([
      Polyline(
        id: 'metro',
        options: PolylineOptionsMessage(
          points: metroRoute,
          width: 3,
          color: Colors.blue.withOpacity(0.5).value,
        ),
      ),
    ]);
  }
